CREATE POLICY "rotina_avatar_own_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'rotina-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "rotina_avatar_own_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'rotina-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "rotina_avatar_own_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'rotina-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "rotina_avatar_own_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'rotina-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);